import { beforeEach, describe, it, expect, vi } from "vitest";
import { serveStatic, type ServeStaticOptions } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";
import * as h3 from "../src/index.ts";

const ETAG = '"v1"';
const MTIME = 1_700_000_000_000;
const CONTENT = "0123456789";

describe("public API", () => {
  it("does not export anything new for Range support", () => {
    expect(Object.keys(h3).sort()).toMatchInlineSnapshot();
  });
});

describeMatrix("serve static range", (t, { it, expect }) => {
  let opts: ServeStaticOptions;

  beforeEach(() => {
    opts = {
      getMeta: vi.fn(() => ({
        type: "text/plain",
        etag: ETAG,
        mtime: MTIME,
        size: CONTENT.length,
      })),
      getContents: vi.fn(() => CONTENT),
    };
    t.app.all("/**", (event) => serveStatic(event, opts));
  });

  // RF-01
  it("advertises accept-ranges on GET and HEAD without Range", async () => {
    const res = await t.fetch("/file.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(CONTENT);

    const head = await t.fetch("/file.txt", { method: "HEAD" });
    expect(head.status).toBe(200);
    expect(head.headers.get("accept-ranges")).toBe("bytes");
  });

  // RF-02
  it("serves bytes=a-b as 206", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
