  });

  // RF-01
  it("advertises accept-ranges on GET and HEAD without Range", async () => {
    const res = await t.fetch("/file.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(CONTENT);

    const head = await t.fetch("/file.txt", { method: "HEAD" });
    expect(head.status).toBe(200);
    expect(head.headers.get("accept-ranges")).toBe("bytes");
  });

  // RF-02
  it("serves bytes=a-b as 206", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe("2345");
  });

  // RF-03
  const suffixCases: [string, string][] = [
    ["bytes=7-", "7-9"],
    ["bytes=-3", "7-9"],
    ["bytes=-99", "0-9"],
    ["bytes=5-99", "5-9"],
  ];
  for (const [range, expected] of suffixCases) {
    it(`serves ${range} as ${expected}`, async () => {
      const res = await t.fetch("/file.txt", { headers: { range } });
      const [start, end] = expected.split("-").map(Number);
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe(`bytes ${expected}/10`);
      expect(res.headers.get("content-length")).toBe(String(end! - start! + 1));
      expect(await res.text()).toBe(CONTENT.slice(start, end! + 1));
    });
  }

  // RF-04
  it("answers HEAD with Range as 206 without a body or getContents", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD", headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(await res.text()).toBe("");
    expect(opts.getContents).not.toHaveBeenCalled();
  });

  // RF-05
  for (const range of ["bytes=10-", "bytes=10-12", "bytes=-0"]) {
    it(`answers ${range} with 416`, async () => {
      const res = await t.fetch("/file.txt", { headers: { range } });
      expect(res.status).toBe(416);
      expect(res.headers.get("content-range")).toBe("bytes */10");
      expect(res.headers.get("content-length")).toBe("0");
      expect(await res.text()).toBe("");
    });
  }

  it("answers any Range with 416 for an empty asset", async () => {
    opts.getMeta = vi.fn(() => ({ etag: ETAG, size: 0 }));
    opts.getContents = vi.fn(() => "");
    const res = await t.fetch("/empty.txt", { headers: { range: "bytes=0-0" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */0");
    expect(res.headers.get("content-length")).toBe("0");
  });

