  if (!event.res.headers.get("content-type")) {
    if (meta.type) {
      event.res.headers.set("content-type", meta.type);
    } else {
      // `/app.js.gz` is still `text/javascript`: resolve the requested asset's
      // type, not the extension of its precompressed variant.
      const ext = getExtension(assetId);
      const type = ext ? (options.getType?.(ext) ?? getType(ext)) : undefined;
      if (type) {
        event.res.headers.set("content-type", type);
      }
    }
  }

  if (meta.encoding && !event.res.headers.get("content-encoding")) {
    event.res.headers.set("content-encoding", meta.encoding);
  }

  if (meta.size !== undefined && meta.size > 0 && !event.res.headers.get("content-length")) {
    event.res.headers.set("content-length", meta.size + "");
  }

  // Runs after the 304 above, so `if-none-match` wins over `range` (RFC 9110 section 13.2.2).
  // `if-range` is only read alongside a `range` (RFC 9110 section 13.1.5).
  const size = meta.size;
  const ifRange = event.req.headers.get("if-range");
  const range =
    event.req.headers.has("range") &&
    size !== undefined &&
    Number.isSafeInteger(size) &&
    size >= 0 &&
    (ifRange === null || matchesIfRange(ifRange, { etag: meta.etag, lastModified: mtimeDate }))
      ? parseRange(event.req.headers.get("range")!, size)
      : undefined;

  // A `range` that does not match `if-range` is ignored whole: neither 206 nor 416.
  if (range === "unsatisfiable") {
    // `event.res.headers` is merged over the HTTPResponse, so this overrides the asset size set above.
    event.res.headers.set("content-range", `bytes */${size}`);
    event.res.headers.set("content-length", "0");
    return new HTTPResponse(null, { status: 416, statusText: "Range Not Satisfiable" });
  }

  if (range) {
    const length = range.end - range.start + 1;
    // Unlike the full-body `content-length` above, a valid range always wins over an
    // explicit `content-length` header (the range is what the body contains).
    event.res.headers.set("content-range", `bytes ${range.start}-${range.end}/${size}`);
    event.res.headers.set("content-length", String(length));
    if (event.req.method === "HEAD") {
      return new HTTPResponse(null, { status: 206, statusText: "Partial Content" });
    }
    const contents = await options.getContents(id);
    return new HTTPResponse(contents ? await sliceBody(contents, range.start, length) : null, {
      status: 206,
      statusText: "Partial Content",
    });
  }

  if (event.req.method === "HEAD") {
    return new HTTPResponse(null, { status: 200 });
  }

  const contents = await options.getContents(id);
  return new HTTPResponse(contents || null, { status: 200 });
}

// --- Internal Utils ---

// `qvalue` grammar (RFC 9110 section 12.4.2).
const WEIGHT_RE = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/;

/**
 * Resolve the configured encoding extensions a request accepts, most preferred first.
 *
 * Coding names are case-insensitive, `q=0` means "not acceptable", `*` matches
 * any coding not listed explicitly and equal weights keep header order, with
 * explicitly listed codings ahead of `*` matches (RFC 9110 section 12.5.3).
 */
function parseAcceptEncoding(header?: string, encodingMap?: Record<string, string>): string[] {
  if (!encodingMap || !header) {
    return [];
  }
  const extensions = new Map<string, string>();
  for (const [name, ext] of Object.entries(encodingMap)) {
    extensions.set(normalizeCoding(name), ext);
  }
  // Coding -> weight, in header order. The first occurrence of a coding wins.
  const weights = new Map<string, number>();
  let wildcard: number | undefined;
  for (const part of header.split(",")) {
    const [rawName = "", ...params] = part.split(";");
    const name = normalizeCoding(rawName);
    if (name !== "*" && !extensions.has(name)) {
      continue;
    }
    const qParam = params.find((p) => /^\s*q\s*=/i.test(p));
    const qValue = qParam?.slice(qParam.indexOf("=") + 1).trim();
    // An unparsable weight drops the coding: identity is always a safe fallback,
    // while guessing `1` could force a coding the client tried to refuse.
    const q = qValue === undefined ? 1 : WEIGHT_RE.test(qValue) ? Number(qValue) : 0;
    if (name === "*") {
      wildcard ??= q;
    } else if (!weights.has(name)) {
      weights.set(name, q);
    }
  }
  if (wildcard) {
    for (const name of extensions.keys()) {
      if (!weights.has(name)) {
        weights.set(name, wildcard);
      }
    }
  }
  const accepted = [...weights]
    .filter(([, q]) => q > 0)
    .sort((a, b) => b[1] - a[1])
    .map(([name]) => extensions.get(name)!);
  return [...new Set(accepted)];
}

/** Lowercase a coding name and resolve the `x-gzip` / `x-compress` aliases (RFC 9110 section 8.4.1). */
function normalizeCoding(name: string): string {
  const coding = name.trim().toLowerCase();
  return coding === "x-gzip" || coding === "x-compress" ? coding.slice(2) : coding;
}

function idSearchPaths(id: string, encodings: string[], indexNames: string[]) {
  const ids: { id: string; assetId: string }[] = [];

  for (const suffix of ["", ...indexNames]) {
    const assetId = `${id}${suffix}`;
    for (const encoding of [...encodings, ""]) {
      ids.push({ id: `${assetId}${encoding}`, assetId });
    }
  }

  return ids;
}

type ByteRange = { start: number; end: number };

/**
 * Parse a single `bytes` range against the representation size (RFC 9110 sections 14.1 and 14.1.1).
 *
 * Returns the inclusive range, `"unsatisfiable"` when no byte falls in it (416), or
 * `undefined` to ignore the header and serve the full body (200).
 */
function parseRange(header: string, size: number): ByteRange | "unsatisfiable" | undefined {
  const match = /^bytes=(\d*)-(\d*)$/i.exec(header);
  if (!match) {
    return undefined;
  }
  const [, first = "", last = ""] = match;
  if (first === "" && last === "") {
    return undefined;
  }
  const from = first === "" ? undefined : Number(first);
  const to = last === "" ? undefined : Number(last);
  if (
    (from !== undefined && !Number.isSafeInteger(from)) ||
    (to !== undefined && !Number.isSafeInteger(to))
  ) {
    return undefined;
  }
  // A range whose last position precedes its first is syntactically invalid.
  if (from !== undefined && to !== undefined && to < from) {
    return undefined;
  }
  if (size === 0) {
    return "unsatisfiable";
  }
  // Suffix form `-k`: the last `k` bytes, or the whole body when `k` exceeds the size.
  if (from === undefined) {
    if (to === 0) {
      return "unsatisfiable";
    }
    return { start: Math.max(size - to!, 0), end: size - 1 };
  }
  if (from >= size) {
    return "unsatisfiable";
  }
  return { start: from, end: to === undefined ? size - 1 : Math.min(to, size - 1) };
}

/**
 * Strong comparison of `if-range` against the current validators (RFC 9110 section 13.1.5).
 *
 * A weak ETag never matches. Dates must match the exact `toUTCString()` form and the
 * `Last-Modified` value. The RFC's extra rule for dates (last-modified at least one
 * second before the date) is not applied, so an exact match is the only way to match.
 */
function matchesIfRange(
  ifRange: string,
  validators: { etag?: string; lastModified?: Date },
): boolean {
  if (ifRange.startsWith("W/")) {
    return false;
  }
  if (ifRange.startsWith('"')) {
    const { etag } = validators;
    return etag !== undefined && !etag.startsWith("W/") && etag === ifRange;
  }
  return (
    validators.lastModified !== undefined && ifRange === validators.lastModified.toUTCString()
  );
}

/**
 * Return the bytes `[start, start + length)` of a body without reading more of it than needed.
 */
async function sliceBody(contents: BodyInit, start: number, length: number): Promise<BodyInit> {
  const end = start + length;
  if (typeof contents === "string") {
    return new TextEncoder().encode(contents).subarray(start, end);
  }
  if (contents instanceof Blob) {
    return contents.slice(start, end);
  }
  if (contents instanceof ArrayBuffer) {
    return new Uint8Array(contents, start, length);
  }
  if (ArrayBuffer.isView(contents)) {
    return new Uint8Array(contents.buffer, contents.byteOffset + start, length);
  }
  if (contents instanceof ReadableStream) {
    return sliceStream(contents, start, end);
  }
  // Other body types (FormData, URLSearchParams) have no byte offsets, so they are read whole.
  return (await new Response(contents).blob()).slice(start, end);
}

/**
 * Discard the bytes before `start` and stop at `end`. Stopping early terminates the
 * transform, which cancels the source stream.
 */
function sliceStream(
  stream: ReadableStream<Uint8Array>,
  start: number,
  end: number,
): ReadableStream<Uint8Array> {
  let offset = 0;
  return stream.pipeThrough(
    new TransformStream<Uint8Array, Uint8Array>({
      transform(chunk, controller) {
        const chunkStart = offset;
        const chunkEnd = offset + chunk.byteLength;
        offset = chunkEnd;
        if (chunkEnd <= start) {
          return;
        }
        const from = Math.max(start - chunkStart, 0);
        const to = Math.min(end - chunkStart, chunk.byteLength);
        controller.enqueue(chunk.subarray(from, to));
        if (chunkEnd >= end) {
          controller.terminate();
        }
      },
    }),
  );
}

