      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe(`bytes ${expected}/10`);
      expect(res.headers.get("content-length")).toBe(String(end! - start! + 1));
      expect(await res.text()).toBe(CONTENT.slice(start, end! + 1));
    });
  }

  // RF-04
  it("answers HEAD with Range as 206 without a body or getContents", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD", headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(await res.text()).toBe("");
    expect(opts.getContents).not.toHaveBeenCalled();
  });

  // RF-05
  for (const range of ["bytes=10-", "bytes=10-12", "bytes=-0"]) {
    it(`answers ${range} with 416`, async () => {
      const res = await t.fetch("/file.txt", { headers: { range } });
      expect(res.status).toBe(416);
      expect(res.headers.get("content-range")).toBe("bytes */10");
      expect(res.headers.get("content-length")).toBe("0");
      expect(await res.text()).toBe("");
    });
  }

  it("answers any Range with 416 for an empty asset", async () => {
    opts.getMeta = vi.fn(() => ({ etag: ETAG, size: 0 }));
    opts.getContents = vi.fn(() => "");
    const res = await t.fetch("/empty.txt", { headers: { range: "bytes=0-0" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */0");
    expect(res.headers.get("content-length")).toBe("0");
  });

  // RF-06
  const ignoredRanges = [
    "bytes=abc",
    "items=0-1",
    "bytes=0-1,4-5",
    "bytes=5-2",
    "bytes=-",
    "bytes=-1x",
    "bytes= 1-2",
  ];
  for (const range of ignoredRanges) {
    it(`ignores malformed or unsupported Range ${range}`, async () => {
      const res = await t.fetch("/file.txt", { headers: { range } });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(res.headers.get("content-length")).toBe("10");
      expect(await res.text()).toBe(CONTENT);
    });
  }

  // RF-07
  it("ignores Range when getMeta has no size", async () => {
    opts.getMeta = vi.fn(() => ({ etag: ETAG, mtime: MTIME }));
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(CONTENT);
  });

  // RF-08
  it("applies Range when If-Range matches the strong ETag", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "if-range": ETAG },
    });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe(CONTENT);
  });

  const mismatchedIfRange = [
    '"v0"',
    'W/"v1"',
    new Date(MTIME + 1000).toUTCString(),
    "2023-11-14T22:13:20Z",
  ];
  for (const ifRange of mismatchedIfRange) {
    it(`ignores Range when If-Range is ${ifRange}`, async () => {
      const res = await t.fetch("/file.txt", {
        headers: { range: "bytes=0-9", "if-range": ifRange },
      });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(await res.text()).toBe(CONTENT);
    });
  }

  it("applies Range when If-Range matches Last-Modified", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-1", "if-range": new Date(MTIME).toUTCString() },
    });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("01");
  });

  it("ignores If-Range when there is no Range", async () => {
    const res = await t.fetch("/file.txt", { headers: { "if-range": '"v0"' } });
    expect(res.status).toBe(200);
    expect(await res.text()).toBe(CONTENT);
  });

  // RF-09
  it("answers 304 before evaluating Range", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "if-none-match": ETAG },
    });
    expect(res.status).toBe(304);
    expect(await res.text()).toBe("");
    expect(opts.getContents).not.toHaveBeenCalled();
  });

  it("answers 304 instead of 416 when the validator matches", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=99-", "if-none-match": ETAG },
    });
    expect(res.status).toBe(304);
  });

  it("answers 404 for a missing asset with Range", async () => {
    opts.getMeta = vi.fn(() => undefined);
    const res = await t.fetch("/missing.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(404);
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("falls through for a missing asset with Range", async () => {
    opts.getMeta = vi.fn(() => undefined);
    opts.fallthrough = true;
    t.app.use(() => "next");
    const res = await t.fetch("/missing.txt", { headers: { range: "bytes=0-9" } });
    expect(await res.text()).toBe("next");
  });

  it("answers 405 with Allow for POST with Range", async () => {
    const res = await t.fetch("/file.txt", {
      method: "POST",
      headers: { range: "bytes=0-9" },
      body: "x",
    });
    expect(res.status).toBe(405);
    expect(res.headers.get("allow")).toBe("GET, HEAD");
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("falls through for POST with Range", async () => {
    opts.fallthrough = true;
    t.app.use(() => "next");
    const res = await t.fetch("/file.txt", {
      method: "POST",
      headers: { range: "bytes=0-9" },
      body: "x",
    });
    expect(await res.text()).toBe("next");
  });

  // RF-10
  it("applies Range to the precompressed variant", async () => {
    opts.encodings = { gzip: ".gz" };
    opts.getMeta = vi.fn((id) =>
      id === "/app.js.gz" ? { etag: ETAG, encoding: "gzip", size: 20 } : undefined,
    );
    opts.getContents = vi.fn(() => "abcdefghijklmnopqrst");
    const res = await t.fetch("/app.js", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-9" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-length")).toBe("10");
    expect(res.headers.get("content-range")).toBe("bytes 0-9/20");
    expect(res.headers.get("vary")).toBe("accept-encoding");
    // Node's fetch decodes `content-encoding: gzip` itself, so the raw bytes are only checked on web.
    if (t.target === "web") {
      expect(await res.text()).toBe("abcdefghij");
    }
  });

  // D-05: body slicing per BodyInit type
  const bodies: [string, () => BodyInit][] = [
    ["string", () => CONTENT],
    ["Blob", () => new Blob([CONTENT])],
    ["ArrayBuffer", () => new TextEncoder().encode(CONTENT).buffer],
    ["Uint8Array", () => new TextEncoder().encode(CONTENT)],
  ];
  for (const [name, body] of bodies) {
    it(`slices a ${name} body`, async () => {
      opts.getContents = vi.fn(body);
      const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
      expect(res.status).toBe(206);
      expect(await res.text()).toBe("2345");
    });
  }

  it("slices a ReadableStream body across chunks and cancels the source early", async () => {
    const encoder = new TextEncoder();
    const chunks = ["01", "234"].map((c) => encoder.encode(c));
    const cancel = vi.fn();
    // Never closes on its own, so `cancel` can only be reached by stopping early.
    opts.getContents = vi.fn(
      () =>
        new ReadableStream<Uint8Array>({
          pull(controller) {
            controller.enqueue(chunks.shift() ?? encoder.encode("56789"));
          },
          cancel,
        }),
    );
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
    expect(cancel).toHaveBeenCalled();
  });

  // D-06
  it("lets a valid Range override an explicit content-length", async () => {
    opts.headers = { "content-length": "999" };
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("4");
  });
});
